DROP TABLE IF EXISTS `inventario_radio`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventario_radio` (
  `id` int NOT NULL AUTO_INCREMENT,
  `poliza` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `no_consecutivo` int DEFAULT NULL,
  `fecha_registro` date DEFAULT NULL,
  `marca` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modelo` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serie_matricula` text COLLATE utf8mb4_unicode_ci,
  `estatus_tramite` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inventario_interno` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_equipo` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado_fisico` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `adscripcion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario_asignado` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `accesorios` text COLLATE utf8mb4_unicode_ci,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `importe_convenio` decimal(15,2) DEFAULT '0.00',
  `tipo_pago` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comprobante_pago` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `foto_equipo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `visto_bueno` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_visto_bueno` date DEFAULT NULL,
  `anio_vigencia` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `no_expediente` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_dano_reclamacion` text COLLATE utf8mb4_unicode_ci,
  `tipo_siniestro` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_bien` text COLLATE utf8mb4_unicode_ci,
  `fecha_siniestro` date DEFAULT NULL,
  `no_siniestro` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `despacho` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estatus` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reclamo` text COLLATE utf8mb4_unicode_ci,
  `aseguradora` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6955 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
